// ExpectedStat's creature values at the character level.
var CreatureHealthMaxLevel = creatureRowByLevel[CharacterLevel].Health
var CreatureArmorMaxLevel = creatureRowByLevel[CharacterLevel].Armor
var CreatureAutoAttackDpsMaxLevel = creatureRowByLevel[CharacterLevel].AutoAttackDps

// The creature row of a level, for a target of that level, and whether the game files carry it.
func CreatureRowAt(level int32) (creatureRow, bool) {
	row, ok := creatureRowByLevel[level]
	return row, ok
}

var CritPerAgiMaxLevel = critPerAgiByLevel[CharacterLevel]
var CritPerIntMaxLevel = critPerIntByLevel[CharacterLevel]

// Base mana and base crit at the character level, added to each class's base row.
var ExtraClassBaseStats = extraClassBaseStatsAtLevel(CharacterLevel)

func extraClassBaseStatsAtLevel(level int32) map[proto.Class]stats.Stats {
	extra := map[proto.Class]stats.Stats{proto.Class_ClassUnknown: {}}
	for class, mana := range baseManaByLevel[level] {
		extra[class] = stats.Stats{stats.Mana: mana, stats.SpellCritPercent: spellCritBase[class], stats.PhysicalCritPercent: physicalCritBase[class]}
	}
	return extra
}
